import{_ as t,o as i,c as a,a4 as r}from"./chunks/framework.vNSRaLQv.js";const c=JSON.parse('{"title":"P2P 组记录","description":"","frontmatter":{"title":"P2P 组记录","date":"2026-06-26T00:00:00.000Z"},"headers":[],"relativePath":"posts/P2P组网选型与折腾记录.md","filePath":"posts/P2P组网选型与折腾记录.md"}'),l={name:"posts/P2P组网选型与折腾记录.md"};function o(s,e,d,n,h,p){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="p2p-组记录" tabindex="-1">P2P 组记录 <a class="header-anchor" href="#p2p-组记录" aria-label="Permalink to &quot;P2P 组记录&quot;">​</a></h1><h2 id="_1-核心需求" tabindex="-1">1. 核心需求 <a class="header-anchor" href="#_1-核心需求" aria-label="Permalink to &quot;1. 核心需求&quot;">​</a></h2><ul><li>几个朋友之间组建纯 P2P 隔离网络</li><li>像“开房间”一样简单（无复杂邀请/账号绑定）</li><li>暴露本机端口互通服务（真局域网体验）免费、轻量、安全隔离（防朋友误操作）无公网 IP、无服务器预算</li></ul><h2 id="_2-方案对比" tabindex="-1">2. 方案对比 <a class="header-anchor" href="#_2-方案对比" aria-label="Permalink to &quot;2. 方案对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Tailscale</th><th>ZeroTier</th><th>n2n / Yggdrasil</th></tr></thead><tbody><tr><td>心智模型</td><td>企业级零信任网络</td><td>游戏开房/宿舍网</td><td>纯技术向 P2P</td></tr><tr><td>加入方式</td><td>账号绑定 + 邮件邀请</td><td>输入 Network ID 即</td><td>命令行配置 supernode/community</td></tr><tr><td>注册门槛</td><td>GitHub/Google OAuth</td><td>邮箱+密码（仅房主）</td><td>无需注册</td></tr><tr><td>网络层级</td><td>三层（IP路由）</td><td>二层（虚拟以太网）/三层可选</td><td>\\局域网协议支持</td></tr><tr><td>开源程度</td><td>客户端开源，协调服务器闭源，Planet 闭源</td><td>全栈开源自建服务器</td><td>不支持（官方 SaaS）</td></tr><tr><td>上手难度</td><td>低但逻辑重）极低</td><td>高适合场景</td><td>企业办公、长期稳定组网</td></tr></tbody></table><h2 id="_3-最终选择-zerotier" tabindex="-1">3. 最终选择：ZeroTier <a class="header-anchor" href="#_3-最终选择-zerotier" aria-label="Permalink to &quot;3. 最终选择：ZeroTier&quot;">​</a></h2><h3 id="选择理由-开房间-模式完美契合直觉-创建-network-→-拿到-id-→-朋友输入即入" tabindex="-1">选择理由 “开房间”模式完美契合直觉：创建 Network → 拿到 ID → 朋友输入即入 <a class="header-anchor" href="#选择理由-开房间-模式完美契合直觉-创建-network-→-拿到-id-→-朋友输入即入" aria-label="Permalink to &quot;选择理由 “开房间”模式完美契合直觉：创建 Network → 拿到 ID → 朋友输入即入&quot;">​</a></h3><ul><li>真二层虚拟以太网，暴露零限制，体验等同于物理局域网</li><li>个人免费，50 设备上限足够</li><li>开源，协议透明，安全性可审计</li><li>安装包仅 ~10MB，资源占用极低</li></ul><h3 id="已知局限" tabindex="-1">已知局限 <a class="header-anchor" href="#已知局限" aria-label="Permalink to &quot;已知局限&quot;">​</a></h3><ul><li>Planet 服务器闭源（与 Tailscale 同类问题）</li><li>房间内默认全通，无内置细粒度 ACL</li><li>NAT 穿透成功率略低于 Tailscale 4. 部署步骤</li></ul><h3 id="第一步-建房-仅房主" tabindex="-1">第一步：建房（仅房主） <a class="header-anchor" href="#第一步-建房-仅房主" aria-label="Permalink to &quot;第一步：建房（仅房主）&quot;">​</a></h3><ol><li>访问 <a href="https://my.zerotier.com" target="_blank" rel="noreferrer">https://my.zerotier.com</a> 注册账号（邮箱+密码）</li><li>点击 Create A Network，获取 16 位 Network ID</li><li>在 Members 页面勾选 Authorize 允许新成员自动加入（或手动审批）### 第二步：进房（所有成员）</li><li>下载安装 ZeroTier One 客户端（Windows/Mac/Android/i 打开客户端 → Join Network → → 点击 Join等待房主授权（若开启自动授权则即时生效）</li></ol><h3 id="第三步-验证连通" tabindex="-1">第三步：验证连通 <a class="header-anchor" href="#第三步-验证连通" aria-label="Permalink to &quot;第三步：验证连通&quot;">​</a></h3><ol><li>控制台确认设备在线且分配虚拟 IP（如 192.168.191.x）\\互相 ping 虚拟 IP 验证连通性 3 开启本机服务绑定 0..0.0），对方用 <code>虚拟IP:</code> 访问</li></ol><h2 id="_5-安全加固建议" tabindex="-1">5. 安全加固建议 <a class="header-anchor" href="#_5-安全加固建议" aria-label="Permalink to &quot;5. 安全加固建议&quot;">​</a></h2><p>由于 ZeroTier 无内置 ACL，需自行补防护层：\\ <strong>Windows 防火墙</strong>：将 ZeroTier 网卡设为专用网络</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">Get-NetConnectionProfile</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> -</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">InterfaceAlias </span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">ZeroTier One</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> |</span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;"> Set-NetConnectionProfile</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> -</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">NetworkCategory Private</span></span></code></pre></div><ul><li><strong>应用层认证</strong>FileBrowser 设强密码、API 加 Token、数据库不暴露远程端口最小暴露原则**：仅开放必要端口，敏感服务绑定 localhost + SSH 隧道</li><li><strong>定期审计</strong>：检查控制台 Members 列表，移除未知设备6. 踩坑记录</li></ul><p>不适配原因 -级 IAM 逻辑与“朋友临时组网”心智模型严重冲突 邀请制流程繁琐，朋友需注册账号并等待邮件确认</p><ul><li>三层不支持广播/mDNS，部分局域网功能缺失</li><li>控制台是基础设施管理面板，非服务导航页，初次使用感“差味道”</li></ul><h3 id="zerotier-注意事项" tabindex="-1">ZeroTier 注意事项 <a class="header-anchor" href="#zerotier-注意事项" aria-label="Permalink to &quot;ZeroTier 注意事项&quot;">​</a></h3><ul><li>首次安装后务必设置防火墙为专用网络否则入站连接被拦截</li><li>随身 WiFi / 对称 NAT 环境可能导致直连失败，走中继时速度下降明显Network ID）等同于凭证，切勿泄露给非信任人员</li></ul><h2 id="_7-后续优化方向若直连率低-可自建-moon-节点加速-公网-vps-若服务增多-可部署-homer-heimdall-作为静态导航页-挂tier-网络内-若对闭源-planet-无法接受-可迁移至-n2n-自建-supernode-或-yggdrasil-纯-p2p" tabindex="-1">7. 后续优化方向若直连率低，可自建 Moon 节点加速（公网 VPS）若服务增多，可部署 Homer/Heimdall 作为静态导航页（挂Tier 网络内 若对闭源 Planet 无法接受，可迁移至 n2n（自建 supernode）或 Yggdrasil（纯 P2P） <a class="header-anchor" href="#_7-后续优化方向若直连率低-可自建-moon-节点加速-公网-vps-若服务增多-可部署-homer-heimdall-作为静态导航页-挂tier-网络内-若对闭源-planet-无法接受-可迁移至-n2n-自建-supernode-或-yggdrasil-纯-p2p" aria-label="Permalink to &quot;7. 后续优化方向若直连率低，可自建 Moon 节点加速（公网 VPS）若服务增多，可部署 Homer/Heimdall 作为静态导航页（挂Tier 网络内 若对闭源 Planet 无法接受，可迁移至 n2n（自建 supernode）或 Yggdrasil（纯 P2P）&quot;">​</a></h2><hr><p><em>文档生成时间：2026-06-26</em><em>适用版本Tier One 114.x /1.98.x</em></p>',25)])])}const P=t(l,[["render",o]]);export{c as __pageData,P as default};
